NAME = 'GerOffBiSt: Offene Bibel - Studienfassung'
BOOK = 'Ezra'

CHAPTERS = {
    4: {
        8: 'Rehum [der] Befehlshaber und Schimschai der Schreiber schrieben einen Brief wegen (gegen) Jerusalem an den König Artaxerxes (Artachschaste) wie folgt:„',
        9: 'Die Absender: Rehum [der] Befehlshaber, Schimschai der Schreiber und ihre übrigen Amtskollegen (Mitarbeiter), die Richter (Diniter) und Gesandten (Beamten; Apharsatchiter), Beamten (Schreiber, Aufseher; Tripolitaner), Regionalgouverneure (Beamten, Verwalter; Perser), die Leute von Erech (Erechiter), Babel (Babylonier) [und] Susa (Susaniter), das sind die (Dehawiter) Elamiter,',
        10: 'und die übrigen Völker, die der große und berühmte (edle, vornehme) Asenappar (Osnappar; Assurbanipal) verschleppt (in die Verbannung geführt) und {sie} in den Ortschaften (Städten) Samarias und in der übrigen [Provinz (Gebieten)] Transeuphrat (»Jenseits des Stroms (Flusses) «) angesiedelt hat. {Absatz} “„',
        11: 'Dies [ist] eine Abschrift (Kopie) des Briefes, den sie an ihn sandten: An den König Artaxerxes (Artachschaste) [schreiben] deine Sklaven (Diener), die Männer [der Provinz] Transeuphrat (»Jenseits des Stroms (Flusses) «). {Absatz}',
        12: 'Dem König sei mitgeteilt (gemeldet, kundgetan), dass die Juden, die von euch zu uns {herauf} gekommen sind, nach Jerusalem gekommen sind. Sie bauen [diese] aufrührerische und böse Stadt wieder auf, {und} sie haben die Mauern (Wälle) [schon fast] fertiggestellt und bessern [gerade] (inspizieren, legen) die Fundamente aus.',
        13: 'Nun sei dem König mitgeteilt (gemeldet, kundgetan): {dass} Wenn diese Stadt wieder aufgebaut wird und die Mauern (Wälle) fertiggestellt sind, werden sie keine Steuern, keine Tribute (Naturalienzahlungen, Ertragsabgaben) und keine Abgaben (Zölle, Grundsteuern) [mehr] entrichten, und [das] wird dem König sicherlich (schließlich; der Schatzkammer) schaden.',
        14: 'Nun, weil wir das Salz des Palastes essen (gegessen haben) und es für uns nicht angemessen ist (sich nicht geziemt), die Beschämung (Schande, Bloßstellung) des Königs mitanzusehen, senden wir jetzt Mitteilung (Nachricht) zum König,',
        15: 'um eine Nachforschung in den Aufzeichnungen deiner Väter zu veranlassen. Und in den Aufzeichnungen wirst du fündig werden und erfahren, dass diese Stadt eine aufrührerische Stadt [ist], {und} [die] Königen und Provinzen Schaden verursacht (hat), und [dass] man in ihrer Mitte seit den Tagen ältester Zeit (von jeher) [immer wieder] Aufstände anzettelt. Aus diesem Grund wurde diese Stadt [auch] zerstört!',
        16: 'Wir teilen dem König deswegen mit: {dass} Wenn diese Stadt wiederaufgebaut worden ist (wird) und die Mauern (Wälle) fertiggestellt sind, wirst du an [der Provinz] Transeuphrat (»Jenseits des Stroms (Flusses) «) keinen Anteil (Provinz) mehr haben! “',
        17: 'Der König sandte das [folgende] Antwortschreiben (Bescheid, Erwiderung): „ An Rehum den Befehlshaber und Schimschai den Schreiber und ihre übrigen Amtskollegen (Mitarbeiter), die in Samaria und in der übrigen [Provinz (Gebieten)] Transeuphrat (»Jenseits des Stroms (Flusses) «) leben. Frieden (Seid gegrüßt)! {Absatz}',
        18: 'Das Schreiben, das ihr an mich gesandt habt, ist mir in Übersetzung (klar) vorgelesen (vorgetragen) worden.',
        19: 'Da (und) habe ich einen Befehl erteilt, sodass (und) man nachgeforscht und herausgefunden hat, dass sich diese Stadt seit den Tagen ältester Zeit (von jeher) gegen Könige auflehnt und [dass immer wieder] Aufruhr und Aufstände in ihr aufkommen.',
        20: 'Zudem (Allerdings; und) haben mächtige Könige über Jerusalem geherrscht und waren Herren in der gesamten [Provinz] Transeuphrat (»Jenseits des Stromes (Flusses) «), und Steuern, Tribute (Naturalienzahlungen, Ertragsabgaben) und Abgaben (Zölle, Grundsteuern) wurden an sie bezahlt.',
        21: 'Nun erteilt Befehl, dass diese Männer zum Einstellen [ihrer Bauarbeiten] gebracht werden und diese Stadt nicht [weiter] aufgebaut werden darf, bis ich den Befehl [dazu] erteile.',
        22: 'Und seid gewarnt, in dieser Angelegenheit (Sache) nachlässig zu handeln! Warum sollte der Schaden (Verletzung) [so] groß werden ([derart] wachsen), dass (um) dem König Schaden entsteht?“',
        23: 'Nachdem die Abschrift (Kopie) vom Schreiben des Königs Artaxerxes (Artachschaste) vor Rehum, {und} Schimschai dem Schreiber und ihren Amtskollegen (Mitarbeitern) verlesen worden war, da begaben (gingen) sie sich eiligst nach Jerusalem zu (gegen) den Juden und zwangen sie mit Gewalt und Waffengewalt zum Einstellen [ihrer Arbeiten].',
        24: 'Zu dieser Zeit (Sofort) hörte die Arbeit am Haus Gottes {, das} in Jerusalem auf und blieb (war) bis ins zweite Jahr der Herrschaft von Darius, des Königs von Persien eingestellt.',
    },
    5: {
        1: 'Damals (und) sprachen (wirkten, prophezeiten, traten als Propheten auf) die Propheten Haggai und Sacharja, der Sohn Iddos, gegenüber den (zu, über, gegen die) Juden {, die} in Juda (Jehud) und {in} Jerusalem Prophezeiungen (eine Prophezeiung) aus im Namen des Gottes Israels, [der] über ihnen [war].',
        2: 'Da (sofort) rafften sich (erhoben sich) Serubbabel, der Sohn Schealtiëls, und Jeschua, der Sohn Jozadaks auf und begannen, das Haus Gottes {, das} in Jerusalem wiederaufzubauen, und mit ihnen [waren auch] die Propheten Gottes, [die] sie unterstützten.',
        3: 'Zu jener Zeit (Damals) kam Tattenai, der Statthalter [der Provinz] Transeuphrat („Jenseits des Stroms (Flusses) “) und Schetar-Bosnai mit (und) ihren Amtskollegen (Mitarbeitern) zu ihnen und fragten (sagten) sie Folgendes: „Wer hat euch Befehl erteilt, dieses Gebäude (Haus) zu bauen und dieses Baugerüst anzufertigen (fertigzustellen)?“',
        4: 'Dann fragten (sagten) sie (wir) sie weiter (Folgendes): „Was sind die Namen der Männer, die dieses Gebäude bauen?“',
        5: 'Aber (und) das Auge ihres Gottes ruhte (war) auf den Ältesten der Juden, sodass (und) sie sie nicht [an der Arbeit] hinderten (zum Einstellen [ihrer Arbeit] zwangen), bis der Bericht zu Darius gelangt war und dann ein Schreiben bezüglich dieser Angelegenheit eingetroffen sei ([die Boten] ein Schreiben... zurückgebracht hätten).',
        6: '[Dies ist] eine Abschrift (Kopie) des Briefes, den Tattenai, der Statthalter [der Provinz] Transeuphrat („Jenseits des Stromes (Flusses) “), mit (und) Schetar-Bosnai und ihren Mitarbeitern (Amtskollegen), den Justizbeamten (Ermittlern; Apharsachitern) an den König Darius sandte.',
        7: 'Sie sandten ihm den Bericht und darin (in dessen Inneren) hieß (lautete, stand) [es] wie folgt: „ Dem König Darius [wünschen wir] völligen (allen) Frieden!',
        8: 'Dem König sei mitgeteilt (gemeldet, kundgetan), dass wir in die Provinz Juda zum Haus des großen Gottes gereist (gekommen, gegangen) sind. {und} Es wird [gerade mit] Quadersteinen wieder aufgebaut und Holz [balken] werden in die Wände gelegt (gesetzt). {und} Diese Arbeit wird sorgfältig (mit großem Eifer) ausgeführt und macht in ihren Händen große Fortschritte.',
        9: 'Da befragten (verhörten) wir diese Ältesten und fragten (sagten) sie Folgendes: »Wer hat euch Befehl erteilt, dieses Gebäude (Haus) zu bauen und dieses Baugerüst anzufertigen (fertigzustellen)?«',
        10: '{und} Außerdem befragten (verhörten) wir sie [nach] ihren Namen, um sie dir mitzuteilen (melden), weil (um) wir die Namen der Männer aufschreiben wollten (sodass wir... konnten), die ihre Anführer (Häupter) [sind].',
        11: 'Und sie gaben uns die folgende Antwort {sagend}: »Wir sind Diener des Gottes des Himmels und der Erde und erbauen das Haus, das einmal [vor] sehr vielen Jahren [hier] gestanden hat (gebaut war). {und} Ein großer König Israels baute und vollendete es.',
        12: 'Weil jedoch unsere Vorfahren (Väter) den Gott des Himmels zornig machten, gab er sie in die Hand (Gewalt) Nebukadnezzars, des Königs von Babel, dem Chaldäer, und er zerstörte dieses Haus {es} und verschleppte (führte in die Verbannung) das Volk nach Babel.',
        13: 'Doch im ersten Jahr von Kyrus, dem König von Babylon, erteilte der König Kyrus Befehl, dieses Haus Gottes wiederaufzubauen (zu erbauen).',
        14: '{und} Außerdem nahm der König Kyrus die Gefäße (Geräte) des Hauses Gottes aus Gold uns Silber, die Nebukadnezzar aus dem Tempel (Palast) {, der} in Jerusalem weggenommen und {sie} zum Tempel (Palast) von Babel gebracht hatte, aus dem Tempel (Palast) von Babel weg und sie wurden [einem Mann] namens Scheschbazzar übergeben, den er [zum] Sonderbevollmächtigten (Statthalter) ernannt hatte (ernannte).',
        15: '{Und} Er sagte zu ihm: »Nimm diese Gefäße (Geräte) {geh} [und] bringe (lagere) sie in den Tempel von Jerusalem! {Und} Das Haus Gottes soll an seinem [ursprünglichen] Ort wieder aufgebaut werden.«',
        16: 'Daraufhin kam jener Scheschbazzar [nach Jerusalem und] legte die Fundamente des Hauses Gottes {, das} in Jerusalem, und von da an {und} bis jetzt wird daran gebaut (war es im Bau) und ist nicht zu Ende gebracht worden.«',
        17: 'Wenn [es] dem König gut [erscheint], sollten deshalb (nun) im Schatzhaus des Königs dort {das} in Babel Nachforschungen angestellt werden, ob es einen vom König Kyrus erteilten Befehl gibt, dieses Haus Gottes in Jerusalem wiederaufzubauen (zu bauen). Und den Willen (die Entscheidung) des Königs hinsichtlich dieser Angelegenheit sollte [man (er)] an uns übermitteln (senden).“',
    },
    6: {
        1: 'Da (sofort) erteilte der König Darius [den entsprechenden] Befehl und man stellte Nachforschungen im Haus der Schriftrollen (Bücher) an, dem Ort (dort), wo in Babel die Schätze aufbewahrt wurden.',
        2: 'Und (doch) in Ekbata (Achmeta), in der Festung der Provinz Medien, fand sich eine Buchrolle, und darin (in ihrem Inneren) stand Folgendes: „ Eine {die} Aufzeichnung (Protokoll, Denkwürdigkeit).',
        3: 'Im ersten Jahr des Königs Kyrus erteilte der König Kyrus [diesen] Befehl. [In Bezug auf] das Haus Gottes in Jerusalem: Das Haus soll wieder aufgebaut werden als eine Stätte (Ort), an der sie Opfer darbringen (opfern), und seine Fundamente sollen erhalten bleiben (seine Brandopfer sollen dargebracht werden). Seine Höhe: 60 Ellen, seine Breite: 60 (20) Ellen.',
        4: '[Anzuwendende Bauweise:] drei Lagen Quadersteine und eine neue Lage Holz [balken]. {und} Die Unkosten erhältst du vom Haus des Königs (aus der Staatskasse) erstattet.',
        5: '{und} Außerdem soll man die Gefäße (Geräte) aus dem vom Haus Gottes aus Gold und Silber zurückgeben, die Nebukadnezzar aus dem Tempel (Palast) {, der} in Jerusalem weggenommen und nach Babel gebracht hat. {und} Sie sollen [zurück] zum Tempel (Palast) {, der} in Jerusalem, zu ihrem [ursprünglichen] Platz, zurückgebracht werden. {und} Stelle (du sollst stellen) [sie] in das Haus Gottes. “„',
        6: 'Deshalb, Tattenai, Statthalter von Transeuphrat (»Jenseits des Stromes (Flusses) «), Schetar Bosnai mit (und) euren Mitarbeitern (Amtskollegen), den Justizbeamten (Ermittlern; Apharsachitern) {, die} in [der Provinz] Transeuphrat (»Jenseits des Stromes (Flusses) «), haltet euch von dort fern!',
        7: 'Lasst die Arbeit an diesem Haus Gottes [weitergehen]! Der Statthalter der Juden und die Ältesten der Juden dürfen (sollen) dieses Haus Gottes an diesem Ort bauen.',
        8: 'Zudem (und) erteile ich [hiermit] (habe ich erteilt) [den] Befehl dazu, wie (was) ihr {mit (für) } den Ältesten jener Juden behilflich sein (verfahren) sollt, um dieses Haus Gottes zu errichten (bauen): {Und} Aus dem Vermögen des Königs, nämlich den Steuern [der Provinz] Transeuphrat (»Jenseits des Stromes (Flusses) «), sollen jenen Männern die Unkosten vollständig (genau) erstattet werden, und zwar ohne zu zögern (ohne Behinderung) (damit [ihre Arbeit] nicht behindert (verzögert) wird).',
        9: 'Und [egal] was benötigt wird, ob (und) Jungstiere, ob (und) Widder oder (und) Lämmer für Brandopfer für den Gott des Himmels, Weizen, Salz, Wein oder (und) Olivenöl, soll ihnen nach Anordnung der Priester {, die} in Jerusalem gegeben sein, Tag für Tag, und zwar ohne Nachlässigkeit,',
        10: 'damit (so dass) sie dem Gott des Himmels wohlgefällige Räucheropfer (Opfer) darbringen und für das Leben (die Gesundheit) des Königs und seiner Söhne beten (können).',
        11: 'Zudem (und) erteile ich [hiermit] (habe ich erteilt) [den] Befehl: {dass} [Wenn] irgendjemand diesen Erlass missachtet (abwandelt), soll (muss) aufgrund dieses [Vergehens] (aufgrund dessen) aus seinem Haus ein Balken (Holz) gezogen werden und er soll (muss) aufrecht darauf gepfählt (daran genagelt) werden. Zudem (und) soll (muss) sein Haus [zu] einem Müllhaufen (Latrine; Trümmerhaufen) gemacht werden.',
        12: 'Und der Gott, der seinen Namen dort wohnen lässt (ließ), möge (soll) jeden König und [jedes] Volk zu Fall bringen (stürzen, demütigen), die ihre Hand ausstrecken, um [diesen Erlass] zu missachten, [also] um dieses Haus Gottes {, das} in Jerusalem zu zerstören. Ich, Darius, habe (erteile [hiermit]) [diesen] Befehl erteilt. Er soll sehr genauestens befolgt (ausgeführt) werden! “',
        13: 'Daraufhin befolgten (führten aus, taten, verfuhren) Tattenai, der Statthalter von Transeuphrat („Jenseits des Stromes (Flusses) “), Schetar Bosnai und ihre Mitarbeiter (Amtskollegen) die erfolgten Angaben, die der König Darius gesandt hatte, sehr sorgfältig (gewissenhaft, ganz genau).',
        14: 'Und die Ältesten der Juden bauten und machten große Fortschritte durch die (entsprechend den) Prophezeiungen (Predigten; Prophezeiung) des Propheten Haggai und von Sacharja, dem Sohn Iddos. {und} Sie bauten [den Tempel] und stellten [ihn] fertig nach der Anweisung (dem Befehl) des Gottes von Israel und nach dem Befehl von Kyrus, {und} Darius und Artaxerxes (Artachschaste), König der Perser.',
        15: '{und} Dieses Haus wurde bis zum (am) dritten Tag des Monats Adar, das [war] im sechsten Jahr der Herrschaft von König Darius, fertig (vollendet),',
        16: 'und die Kinder (Söhne, Nachfahren; Leute) Israels, die Priester und Leviten und die übrigen Deportierten begingen (feierten) die Einweihung dieses Hauses Gottes mit [großer] Freude.',
        17: '{und} Anlässlich der Einweihung dieses Hauses Gottes opferten sie 100 Stiere, 200 Widder, 400 Lämmer und, als Sündopfer für ganz Israel, zwölf Ziegenböcke entsprechend (gemäß) der Zahl der Stämme Israels.',
        18: 'Zudem (und) ernannten (beriefen) Sie Priester in ihren Abteilungen und Leviten in ihren Dienstgruppen (Abteilungen) für den Dienst an Gott {, der} in Jerusalem, wie es im Buch Moses steht.',
    },
    7: {
        11: '„',
        12: 'Artaxerxes (Artachschaste), König der Könige, an Esra den Priester, Schreiber (Sekretär, Schriftgelehrter) des Gesetzes des Gottes des Himmels. Grüße! (Friede!) {Absatz}',
        13: '[Hiermit] erteile ich (habe ich erteilt) Befehl: {dass} Jeder in meinem Reich aus dem Volk Israel und seinen Priestern und Leviten, der bereit ist, nach Jerusalem zu gehen, darf (soll) mit dir gehen.',
        14: 'Denn du bist vom König und seinen Sieben Räten gesandt, um Nachforschungen über Juda (Jehud) und zu Jerusalem anzustellen bezüglich des Gesetzes deines Gottes, das in deiner Hand ist,',
        15: 'und um Silber und Gold zu bringen, das der König und seine Räte dem Gott Israels zum Geschenk machen (spenden; zum Geschenk gemacht haben), dessen Wohnort in Jerusalem [ist],',
        16: 'sowie (und) alles Silber und Gold, das du in der gesamten Provinz Babel bekommen kannst (bekommst), mit den Spenden des Volks und der Priester, die sie für das (zum) Haus ihres Gottes {, das} in Jerusalem spenden.',
        17: 'Demgemäß (deshalb) sollst du mit diesem Geld (Silber) gewissenhaft Stiere, Widder [und] Lämmer sowie (und) die dazugehörigen Speise- und Trankopfer erwerben (einkaufen) und sie auf dem Altar des Hauses eures Gottes {, das} in Jerusalem opfern.',
        18: 'Und was dir und deinen Brüdern [auch] mit dem übrigen (Rest) Silber und Gold, in Übereinstimmung mit (gemäß) dem Willen eures Gottes, gut zu tun erscheint, das dürft ihr tun (tut).',
        19: 'Zudem (und) sollst du (liefere ab) die Gefäße (Geräte) vor dem Gott Jerusalems abliefern, die dir für den Gottesdienst des Hauses deines Gottes gegeben wurden.',
        20: '{und} Den übrigen Bedarf [für] das Haus deines Gottes, den du selbst zu decken (aufzubringen) hast (hättest), darfst du aus dem Schatzhaus des Königs decken.',
        21: 'Zudem (und) erlasse ich (habe ich erlassen), der König Artaxerxes (Artachschaste), [hiermit] Befehl an alle Schatzmeister der [Provinz] Transeuphrat (»Jenseits des Stromes (Flusses) «): {dass} Alles, was Esra, der Priester und Schreiber (Sekretär, Schriftgelehrter) des Gesetzes des Gottes des Himmels, von euch verlangt, [das] soll genauestens befolgt (ausgeführt, getan) (pünktlich geliefert) werden.',
        22: 'Bis zu 100 Talente (Gewichte) Silber, {und} bis zu 100 Kor Weizen, {und} bis zu 100 Bat Wein, {und} bis zu 100 Bat Olivenöl und Salz ohne vorgeschriebene Menge.',
        23: 'Alle [Erfordernisse] aus [der] Anordnung des Gottes des Himmels sollen für das Haus des Gottes des Himmels pünktlich (genauestens, gewissenhaft) bereitgestellt (befolgt, ausgeführt, getan) werden, damit sein Zorn sich nicht gegen die Herrschaft des Königs und seiner Söhne richtet.',
        24: '[Wir] teilen dir außerdem (und) mit, dass es nicht gestattet ist, von irgendeinem der Priester und Leviten, Sänger, Torwachen, Tempeldiener und [anderen] Arbeiter dieses Hauses Gottes Steuern, Tribute (Naturalienzahlungen, Ertragsabgaben) oder (und) Abgaben (Zölle, Grundsteuern) {von ihnen} zu erheben.',
        25: 'Und du, Esra, ernenne nach der Weisheit deines Gottes, die [du] in deiner Hand [hast], Richter (Verwaltungsbeamten) und Rechtsprecher (Richter), die für das ganze Volk {, das} in [der Provinz] Transeuphrat (»Jenseits des Stromes (Flusses) «) Recht sprechen, [wenigstens] für alle diejenigen, die die Gesetze deines Gottes kennen. Und [jeden], der es nicht kennt, sollt ihr [es] lehren (bekannt machen).',
        26: 'Doch (und) jeder, der [den] Gesetzen deines Gottes und den Gesetzen des Königs nicht genauestens gehorcht (folgt, tut), an dem soll das Recht vollstreckt (über den … Urteil gefällt; Gericht gesprochen) werden – ob zum Tod, {oder (ob) } zum Verbannung (körperlichen Bestrafung), oder (ob) zur Beschlagnahmung seines Besitzes (Geldstrafe) und (oder) {zu} einer Gefängnisstrafe.“',
    },
}
